function example() {
  const hydrated = useIsHydrated();
  const isMac = hydrated && /Mac|iPhone|iPad/.test(navigator.userAgent);
  return (
    <Button aria-keyshortcuts={isMac ? 'Meta+K' : 'Control+K'}>
      Search
      <Kbd.Group ml="2">
        {isMac ? <Kbd label="Command">⌘</Kbd> : <Kbd>Ctrl</Kbd>}
        <Kbd>K</Kbd>
      </Kbd.Group>
    </Button>
  );
}
